// Display-only traditional glyph conversion for ring inscriptions; calculation data is unchanged.
const glyphs={罗:'羅',经:'經',卦:'卦',盘:'盤',为:'為',风:'風',泽:'澤',无:'無',云:'雲',阴:'陰',阳:'陽',龙:'龍',鸟:'鳥',节:'節',气:'氣',惊:'驚',蛰:'蟄',满:'滿',种:'種',处:'處',寒:'寒',东:'東',后:'後',观:'觀',讼:'訟',师:'師',贲:'賁',剥:'剝',复:'復',蛊:'蠱',临:'臨',颐:'頤',恒:'恆',壮:'壯',晋:'晉',损:'損',归:'歸',丰:'豐',兑:'兌',涣:'渙',济:'濟',渐:'漸',离:'離',坎:'坎',亨:'亨',历:'曆',数:'數',转:'轉',万:'萬',开:'開',将:'將',时:'時',宫:'宮',岁:'歲',并:'並',应:'應',贞:'貞',亲:'親',简:'簡',辞:'辭',注:'註',释:'釋',亥:'亥'};
